import type { BarSize } from 'components/Chart/types';

export const barSize = {
  xxsmall: 28,
  xsmall: 28,
  small: 32,
  medium: 40,
  large: 48,
  xlarge: 56,
};

export const getBarThickness = (size: BarSize): number => {
  if (size === 'responsive') {
    return barSize.medium;
  }

  return barSize[size];
};

export const variationColorMap = {
  up: '#00810D',
  down: '#A30A0A',
};
